package forth

import (
	"errors"
	"strconv"
	"strings"
)

// Forth evaluates a simple subset of the Forth language.
// Each input line is either a word definition (`: name ... ;`) or a
// sequence of tokens to execute. Words are case-insensitive.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	dict := map[string][]string{} // lowercase name -> expanded token list

	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			if len(tokens) < 3 || tokens[len(tokens)-1] != ";" {
				return nil, errors.New("invalid definition")
			}
			name := strings.ToLower(tokens[1])
			if isNumber(tokens[1]) {
				return nil, errors.New("word name cannot be a number")
			}
			// Expand the definition against the dictionary as it exists
			// now, so that a redefinition captures the old meaning of
			// any words it uses (local scope).
			expanded, err := expand(tokens[2:len(tokens)-1], dict)
			if err != nil {
				return nil, err
			}
			dict[name] = expanded
			continue
		}
		if err := exec(tokens, dict, &stack); err != nil {
			return nil, err
		}
	}
	return stack, nil
}

// expand resolves every token that is already a defined word into its
// (recursively expanded) definition. Numbers and unknown words are kept
// as-is so they can be resolved later at execution time.
func expand(tokens []string, dict map[string][]string) ([]string, error) {
	out := make([]string, 0, len(tokens))
	for _, tok := range tokens {
		if isNumber(tok) {
			out = append(out, tok)
			continue
		}
		def, ok := dict[strings.ToLower(tok)]
		if !ok {
			out = append(out, tok)
			continue
		}
		expanded, err := expand(def, dict)
		if err != nil {
			return nil, err
		}
		out = append(out, expanded...)
	}
	return out, nil
}

func exec(tokens []string, dict map[string][]string, stack *[]int) error {
	for _, tok := range tokens {
		if isNumber(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return err
			}
			*stack = append(*stack, n)
			continue
		}
		name := strings.ToLower(tok)
		if def, ok := dict[name]; ok {
			if err := exec(def, dict, stack); err != nil {
				return err
			}
			continue
		}
		if err := builtin(name, stack); err != nil {
			return err
		}
	}
	return nil
}

func builtin(name string, stack *[]int) error {
	switch name {
	case "+", "-", "*", "/":
		if len(*stack) < 2 {
			return errors.New("insufficient values on the stack")
		}
		b, a := (*stack)[len(*stack)-1], (*stack)[len(*stack)-2]
		*stack = (*stack)[:len(*stack)-2]
		switch name {
		case "+":
			*stack = append(*stack, a+b)
		case "-":
			*stack = append(*stack, a-b)
		case "*":
			*stack = append(*stack, a*b)
		default:
			if b == 0 {
				return errors.New("division by zero")
			}
			*stack = append(*stack, a/b)
		}
	case "dup":
		if len(*stack) < 1 {
			return errors.New("empty stack")
		}
		*stack = append(*stack, (*stack)[len(*stack)-1])
	case "drop":
		if len(*stack) < 1 {
			return errors.New("empty stack")
		}
		*stack = (*stack)[:len(*stack)-1]
	case "swap":
		if len(*stack) < 2 {
			return errors.New("insufficient values on the stack")
		}
		n := len(*stack)
		(*stack)[n-1], (*stack)[n-2] = (*stack)[n-2], (*stack)[n-1]
	case "over":
		if len(*stack) < 2 {
			return errors.New("insufficient values on the stack")
		}
		*stack = append(*stack, (*stack)[len(*stack)-2])
	default:
		return errors.New("undefined word")
	}
	return nil
}

// isNumber reports whether s is a signed integer literal: an optional
// leading '-' followed by one or more ASCII digits.
func isNumber(s string) bool {
	if s == "" {
		return false
	}
	start := 0
	if s[0] == '-' {
		if len(s) == 1 {
			return false
		}
		start = 1
	}
	for _, c := range s[start:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

